window.WPS = window.WPS || {};
WPS.LESSONS = WPS.LESSONS || {};
(function (L) {
  // ===== 図 =====
  var PASTPERF = '<svg viewBox="0 0 220 110" class="lz-fig" role="img" aria-label="過去完了の時間の線。電車が出たのが先、私が着いたのが後、そのあとに今がある"><line x1="10" y1="60" x2="210" y2="60" class="ax"/><path d="M203 55 L210 60 L203 65" class="ax"/><circle cx="55" cy="60" r="4" class="pt"/><circle cx="125" cy="60" r="4" class="pt"/><line x1="185" y1="52" x2="185" y2="68" class="ax"/><text x="28" y="42">電車が出た</text><text x="98" y="42">私が着いた</text><text x="180" y="42">今</text><text x="34" y="82">had left</text><text x="105" y="82">arrived</text><text x="38" y="102">大過去</text><text x="114" y="102">過去</text><text x="174" y="102">現在</text></svg>';
  var FUTPERF = '<svg viewBox="0 0 220 110" class="lz-fig" role="img" aria-label="未来完了の時間の線。今から6時までの間に宿題が終わる"><line x1="10" y1="60" x2="210" y2="60" class="ax"/><path d="M203 55 L210 60 L203 65" class="ax"/><line x1="40" y1="52" x2="40" y2="68" class="ax"/><circle cx="115" cy="60" r="4" class="pt"/><line x1="175" y1="48" x2="175" y2="72" class="cv2"/><text x="35" y="42">今</text><text x="88" y="42">宿題が終わる</text><text x="150" y="42">6時(期限)</text><path d="M42 75 L173 75" class="dash"/><text x="52" y="94">この間のどこかで完了</text><text x="128" y="108">will have finished</text></svg>';
  var AUXSCALE = '<svg viewBox="0 0 220 100" class="lz-fig" role="img" aria-label="推量の助動詞の確信度。左ほど低く右ほど高い。can\'t、may・might、should、must の順"><line x1="15" y1="50" x2="205" y2="50" class="ax"/><path d="M198 45 L205 50 L198 55" class="ax"/><circle cx="25" cy="50" r="4" class="pt"/><circle cx="105" cy="50" r="4" class="pt"/><circle cx="160" cy="50" r="4" class="pt"/><circle cx="192" cy="50" r="4" class="pt"/><text x="12" y="72">can\'t</text><text x="4" y="88">はずがない</text><text x="78" y="36">may / might</text><text x="76" y="72">かもしれない</text><text x="142" y="72">should</text><text x="145" y="88">はずだ</text><text x="176" y="36">must</text><text x="160" y="22">ちがいない</text><text x="80" y="96">← 確信 低い/高い →</text></svg>';

  // ===== 文型 =====
  L.e_h1 = {
    goal: '英文を S(主語)・V(動詞)・O(目的語)・C(補語)に分けて、5つの文型のどれかを見分けられるようになる。',
    intro: '英語は、日本語とちがって【語順が意味を決める】言葉です。「Ken loves Mary.」と「Mary loves Ken.」は単語が同じでも意味が逆になります。どんなに長い英文も、骨組みは5つの型(5文型)のどれかです。骨組みが取れれば、長い文も迷わず読めるようになります。',
    secs: [
      { h: '文の要素は4つ+おまけ', t: '英文の骨組みをつくる要素は次の4つです。\n【S(主語)】…「〜は・〜が」にあたる語。名詞・代名詞。\n【V(動詞)】…「〜する・〜である」にあたる語。\n【O(目的語)】…動詞の動作を受ける相手。「〜を・〜に」にあたる名詞。\n【C(補語)】…S や O が「どんなものか・どんな状態か」を説明する語。名詞か形容詞。\nこのほかの語(場所・時・様子などを表す語句)は【M(修飾語)】と呼び、文型には数えません。in the park、yesterday、very などが M です。\n文型を考えるときは、まず M をかっこでくくって消し、残った S・V・O・C を見ます。' },
      { h: '第1文型 SV と 第2文型 SVC', t: '【第1文型 SV】…S と V だけで文が完成する形。\n例:Birds fly.(鳥は飛ぶ)→ S=Birds、V=fly\n例:My father works (in a bank).(父は銀行で働いている)→ S=My father、V=works、in a bank は M\n【第2文型 SVC】…V の後ろに、S を説明する C がくる形。【S=C】の関係が成り立つのが目印です。\n例:She is a doctor.(彼女は医者だ)→ S=She、V=is、C=a doctor(She=a doctor)\n例:He looks happy.(彼はうれしそうに見える)→ S=He、V=looks、C=happy(He=happy)\nSVC をとる主な動詞:be、become、get、grow、turn(〜になる)/look、seem(〜に見える)/sound(〜に聞こえる)/feel(〜に感じる)/keep、remain(〜のままである)。\nC には形容詞が入ります。He looks happily. とはしません(副詞は C になれません)。' },
      { h: '第3文型 SVO と 第4文型 SVOO', t: '【第3文型 SVO】…V の後ろに、動作の相手 O が1つくる形。S≠O です。\n例:I love music.(私は音楽が大好きだ)→ S=I、V=love、O=music\n【第4文型 SVOO】…「(人)に(物)を〜する」。O が2つ並びます。\n例:He gave me a book.(彼は私に本をくれた)→ S=He、V=gave、O₁=me、O₂=a book\n2つの O は別のもので、me ≠ a book です。\nSVOO は、前置詞を使って SVO に書きかえられます。\n・give、show、tell、send、lend など(相手がいないとできない動作)→【to】:He gave a book to me.\n・buy、make、cook、find など(自分だけでもできる動作)→【for】:She bought a bag for me.' },
      { h: '第5文型 SVOC', t: '【第5文型 SVOC】…O の後ろに、O を説明する C がくる形。【O=C】の関係(O is C)が成り立つのが目印です。\n例:The news made her happy.(その知らせは彼女を喜ばせた)→ S=The news、V=made、O=her、C=happy(she is happy)\n例:We call him Ken.(私たちは彼をケンと呼ぶ)→ S=We、V=call、O=him、C=Ken(he is Ken)\n例:I found the book easy.(その本はやさしいとわかった)→ S=I、V=found、O=the book、C=easy\nSVOC をとる主な動詞:make(O を C にする)、keep・leave(O を C のままにしておく)、call・name(O を C と呼ぶ・名づける)、find・think(O が C だとわかる・思う)。\n【SVOO と SVOC の見分け方】O の後ろの2語の間に be動詞を入れてみます。「O is ○○」が成り立てば SVOC、成り立たなければ SVOO です。',
        ex: [{ q: '次の2文の文型を答え、和訳しよう。\n(1) My mother made me a cake.\n(2) My mother made me angry.', steps: ['(1) S=My mother、V=made。me と a cake の間に be を入れると「I am a cake」で意味が通らない → me ≠ a cake。', '(1) は O が2つの SVOO。「(人)に(物)を作る」の意味。', '(2) me と angry の間に be を入れると「I am angry」で意味が通る → O=C。', '(2) は SVOC。「O を C にする」の意味。'], a: '(1) SVOO:母は私にケーキを作ってくれた。(2) SVOC:母は私を怒らせた。' }] },
      { h: '自動詞と他動詞', t: 'O をとらない動詞を【自動詞】、O をとる動詞を【他動詞】といいます。日本語の感覚で前置詞をつけたり外したりすると、まちがえやすい動詞があります。\n・前置詞が【いらない】他動詞:discuss the plan(× discuss about)、marry him(× marry with)、enter the room(× enter into)、reach the station(× reach to)、approach the town(× approach to)\n・形がまぎらわしい自動詞・他動詞:\n【lie】(横になる・ある/自動詞)lie - lay - lain\n【lay】(〜を置く・横たえる/他動詞)lay - laid - laid\n【rise】(上がる/自動詞)rise - rose - risen\n【raise】(〜を上げる/他動詞)raise - raised - raised\nlie の過去形と lay の原形が同じ lay なので、特に注意します。',
        ex: [{ q: '正しいほうを選ぼう。\n(1) We discussed (the problem / about the problem).\n(2) Please (raise / rise) your hand.', steps: ['(1) discuss は「〜について話し合う」という意味の他動詞。すぐ後ろに O をとるので about は不要。', '(2) your hand という O がある → O をとる他動詞が必要。', 'rise は自動詞(O をとらない)、raise は他動詞(〜を上げる)。'], a: '(1) the problem(私たちはその問題について話し合った)(2) raise(手を挙げてください)' }] }
    ],
    terms: [['S(主語)', '文の主題。「〜は・〜が」にあたる名詞'], ['V(動詞)', '「〜する・〜である」にあたる語。文に必ず1つある'], ['O(目的語)', '動作を受ける名詞。「〜を・〜に」'], ['C(補語)', 'S や O の正体・状態を説明する名詞・形容詞'], ['M(修飾語)', '文型に数えない飾りの語句(副詞・前置詞のかたまりなど)'], ['自動詞/他動詞', 'O をとらない動詞/O をとる動詞']],
    miss: ['He looks happily. のように、C に副詞を入れてしまう(C は形容詞か名詞)。', 'in the park などの前置詞のかたまりを O だと思ってしまう(前置詞+名詞は M)。', 'SVOO と SVOC を区別せず、made me a cake と made me angry を同じ意味で訳す。', 'discuss about、enter into など、他動詞に余計な前置詞をつける。'],
    sum: ['M をかっこでくくり、S・V・O・C だけを見る。', 'SVC は S=C、SVOC は O=C の関係が目印。', 'SVOO は「(人)に(物)を」。to か for で SVO に書きかえられる。', 'C になれるのは名詞と形容詞だけ。', '自動詞・他動詞は、前置詞の有無とセットで覚える。']
  };

  // ===== 時制 =====
  L.e_pastperf = {
    goal: '過去完了(had+過去分詞)を、「過去のある時点より前」を表すときに正しく使えるようになる。',
    intro: '現在完了(have+過去分詞)は、「今」を基準にして、それまでの完了・経験・継続を表しました。【過去完了】は、その基準を「今」から【過去のある時点】に移したものです。「私が駅に着いたとき、電車はもう出てしまっていた」のように、過去の2つの出来事の順番をはっきりさせるときに使います。',
    secs: [
      { h: '形と基本のイメージ', t: '形は【had + 過去分詞】です。主語が何であっても had を使います。\n例:When I arrived at the station, the train had already left.(私が駅に着いたとき、電車はすでに出てしまっていた)\n「着いた(arrived)」が過去の基準点です。電車が出たのはそれよりも前なので、had left になります。\n時間の線で考えると、【大過去(had left)→ 過去(arrived)→ 現在】の順になります。過去完了は、必ず「基準になる過去」とセットで使います。', fig: PASTPERF },
      { h: '過去完了の4つの用法', t: '現在完了と同じく、完了・経験・継続の意味があり、さらに「大過去」の用法があります。\n【完了・結果】過去の時点までに〜してしまっていた。\n例:The movie had already started when we got there.(私たちが着いたとき、映画はもう始まっていた)\n【経験】過去の時点までに〜したことがあった。\n例:I had never seen snow before I went to Hokkaido.(北海道に行くまで、雪を見たことがなかった)\n【継続】過去の時点まで(ずっと)〜していた。\n例:She had lived in Osaka for five years when she moved to Tokyo.(東京へ引っ越したとき、彼女は大阪に5年住んでいた)\n【大過去】過去の出来事より前に起きたことを表す。\n例:I lost the watch my father had given me.(父がくれた時計をなくした)→ くれたのは、なくすより前。' },
      { h: '過去完了進行形', t: '過去のある時点まで、動作が【ずっと続いていた】ことを強調するときは、【had been + 〜ing】を使います。\n例:I had been waiting for an hour when she finally came.(彼女がやっと来たとき、私は1時間ずっと待っていた)\nwait、study、rain など、続けて行う動作に使います。know、like のような状態を表す動詞は進行形にしないので、had known のように過去完了の継続用法で表します。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nBy the time we arrived, the concert ( ).\n① has started ② had started ③ starts ④ will start', steps: ['基準になる時点を探す:we arrived(過去)。', 'コンサートが始まったのは、到着より前。', '「過去より前」なので過去完了 had + 過去分詞。', '現在完了 has started は「今」が基準なので、過去の基準点とは合わない。'], a: '② had started(私たちが着いたときには、コンサートは始まっていた)' }] },
      { h: '過去完了を使わなくてよい場合', t: 'before・after など、出来事の順番が接続詞からはっきり分かるときは、過去形だけで書いてもかまいません。\n例:I went out after I finished my homework.(宿題を終えてから外出した)\n※ after I had finished と過去完了で書いても正しい文です。\nまた、起きた順番どおりに並べるときも過去形で十分です。\n例:I got up, washed my face, and left home.(起きて、顔を洗って、家を出た)\n過去完了が必要なのは、【書いた順番と起きた順番が逆になる】ときです。',
        ex: [{ q: '日本語に合うように、( ) の動詞を正しい形にしよう。\n「私は、前の晩に買った本を読んだ。」\nI read the book I ( buy ) the night before.', steps: ['基準の過去:read(読んだ)。', '本を買ったのは、読むより前(前の晩)。', '文の中では「買った」が後ろに書かれていて、起きた順番と逆 → 過去完了を使う。'], a: 'had bought' }] }
    ],
    terms: [['過去完了', 'had + 過去分詞。過去のある時点を基準にした完了・経験・継続'], ['大過去', '過去の出来事よりもさらに前に起きたことを表す用法'], ['過去完了進行形', 'had been 〜ing。過去の時点まで動作が続いていたことを表す'], ['基準点', '「いつより前か」を決める、文の中の過去の時点']],
    miss: ['基準になる過去がないのに、過去完了を使ってしまう(過去完了は過去の基準点とセット)。', '過去の基準点があるのに、現在完了(has + 過去分詞)を使ってしまう。', 'yesterday、last week など、はっきり過去の時を表す語を現在完了と一緒に使う(I have seen him yesterday. は誤り)。'],
    sum: ['過去完了 = had + 過去分詞。基準は「過去のある時点」。', '大過去 → 過去 → 現在 の順に時間の線にのせて考える。', '用法は 完了・経験・継続・大過去。', '動作の継続を強調するなら had been 〜ing。', '順番が接続詞で明らかなら、過去形だけでもよい。']
  };
  L.e_futperf = {
    goal: '未来完了(will have+過去分詞)を使って、「未来のある時点までに〜しているだろう」を表せるようになる。',
    intro: '「6時までには宿題を終えているだろう」「来年で、ここに住んで10年になる」。このように、【未来のある時点】を基準にして、それまでの完了・経験・継続を言うのが【未来完了】です。過去完了の基準を、今度は未来に移したものと考えると分かりやすくなります。',
    secs: [
      { h: '形と基本のイメージ', t: '形は【will have + 過去分詞】です。主語が3人称単数でも has にはなりません(will の後ろは原形なので have)。\n例:I will have finished my homework by six.(6時までには宿題を終えているだろう)\n基準は「6時」という未来の時点です。今から6時までのどこかで、宿題が終わります。\n目印になるのは【by + 未来の時点】(〜までには)や【by the time 〜】(〜するころまでには)です。', fig: FUTPERF },
      { h: '完了・経験・継続', t: '【完了】未来の時点までに〜してしまっているだろう。\n例:The train will have left by the time we get to the station.(私たちが駅に着くころには、電車は出てしまっているだろう)\n【経験】未来の時点で〜したことになる。\n例:If I see this movie again, I will have seen it three times.(この映画をもう一度見たら、3回見たことになる)\n【継続】未来の時点まで(ずっと)〜していることになる。\n例:By next year, I will have lived here for ten years.(来年で、ここに住んで10年になる)\n動作が続いていることを強調するときは、【will have been 〜ing】(未来完了進行形)を使います。\n例:By five o\'clock, I will have been studying for three hours.(5時で、3時間ずっと勉強していることになる)',
        ex: [{ q: '和訳しよう。\nBy next April, my brother will have worked at the company for twenty years.', steps: ['By next April=来年の4月までに(未来の基準点)。', 'will have worked ... for twenty years=未来完了の継続。', '「その時点で20年働いたことになる」と訳す。'], a: '来年の4月で、兄はその会社に20年勤めたことになる。' }] },
      { h: 'by と until のちがい、by the time の中の時制', t: '【by】は「〜までに」(期限)。その時点までに1回終わればよい、という意味です。未来完了とよく一緒に使います。\n【until(till)】は「〜までずっと」(継続)。その時点まで同じ状態が続きます。\n例:I will wait here until six.(6時までずっとここで待つ)\n例:I will have finished it by six.(6時までには終えているだろう)\nまた、by the time や when の後ろは「時を表す副詞節」なので、未来のことでも【現在形】にします。\n× By the time he will come, … → ○ By the time he comes, I will have cleaned the room.(彼が来るころには、部屋を掃除し終えているだろう)',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nI ( ) this book by the end of this week.\n① will have read ② have read ③ had read ④ read', steps: ['by the end of this week=今週末までに(未来の基準点)。', '未来の時点までの完了なので、will have + 過去分詞。', 'had read は過去の基準点が必要なので合わない。'], a: '① will have read(今週末までにはこの本を読み終えているだろう)' }] }
    ],
    terms: [['未来完了', 'will have + 過去分詞。未来のある時点を基準にした完了・経験・継続'], ['未来完了進行形', 'will have been 〜ing。未来の時点まで動作が続いていることを表す'], ['by', '〜までに(期限)。1回終わればよい'], ['until', '〜までずっと(継続)']],
    miss: ['主語が he・she なので will has としてしまう(will の後ろは必ず原形 have)。', 'by と until を混同する(期限なら by、継続なら until)。', 'By the time he will come のように、時を表す副詞節の中に will を入れる。'],
    sum: ['未来完了 = will have + 過去分詞。', '目印は by + 未来の時点、by the time 〜。', '用法は 完了・経験・継続。継続の強調は will have been 〜ing。', 'by=〜までに、until=〜までずっと。', 'by the time・when の中は、未来のことでも現在形。']
  };
  L.e_tense = {
    goal: '時・条件を表す接続詞の後ろで、未来のことでも現在形を使う理由が分かり、名詞節の if・when と見分けられるようになる。',
    intro: '「明日雨が降ったら、家にいます」を英語にすると、If it rains tomorrow, I will stay home. です。tomorrow なのに will rain ではなく rains です。これは英語の決まりで、【時・条件を表す副詞節の中では、未来のことも現在形で表す】からです。ところが同じ if でも、will を使う場合があります。この単元では、その見分け方を身につけます。',
    secs: [
      { h: '時・条件の副詞節は「現在形」', t: '次の接続詞が作る節(S と V をふくむかたまり)は、文の中で「いつ・どんな条件で」を表す【副詞節】です。\n・時:when(〜するとき)、before(〜する前に)、after(〜した後で)、until(〜するまで)、as soon as(〜するとすぐに)、by the time(〜するころまでに)\n・条件:if(もし〜なら)、unless(〜しない限り)、once(いったん〜すれば)、in case(〜するといけないから)\nこれらの節の中では、【未来のことでも現在形】を使います。\n例:I will call you when I arrive at the station.(駅に着いたら電話します)\n例:If it is sunny tomorrow, we will go on a picnic.(明日晴れたら、ピクニックに行きます)\n未来であることは、主節の will や tomorrow で十分伝わるので、副詞節では現在形にする、と考えるとよいでしょう。' },
      { h: '完了の意味なら現在完了', t: '副詞節の中で「〜し終えたら」と完了の意味を表したいときは、will have + 過去分詞(未来完了)ではなく、【現在完了】を使います。\n例:I will lend you this book when I have finished reading it.(読み終えたら、この本を貸してあげます)\n例:You can go out after you have done your homework.(宿題をしてしまったら、出かけていいですよ)' },
      { h: '名詞節の if・when は「will」を使う', t: 'if が「【〜かどうか】」、when が「【いつ〜するか】」という意味のときは、節が動詞の目的語(名詞のはたらき)になっています。これを【名詞節】といいます。名詞節の中では、未来のことは will で表します。\n例:I don\'t know if it will rain tomorrow.(明日雨が降るかどうか分からない)→ if 節は know の目的語(O)\n例:Please tell me when he will come back.(彼がいつ戻ってくるか教えてください)→ when 節は tell の目的語\n【見分け方】if 節・when 節を取り除いてみます。\n・取り除いても文が成り立つ → 副詞節(現在形)\n 例:I will stay home (if it rains tomorrow). → I will stay home. で文が完成。\n・取り除くと文が成り立たない → 名詞節(will)\n 例:I don\'t know (if it will rain). → I don\'t know. だと「何を?」が欠けて不完全。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\n(1) Let\'s start the meeting as soon as he ( ). ① comes ② will come\n(2) I wonder if he ( ) to the party next week. ① comes ② will come', steps: ['(1) as soon as は「〜するとすぐに」という時の副詞節。取り除いても Let\'s start the meeting. で文が成り立つ。', '(1) 副詞節なので、未来のことでも現在形 comes。', '(2) if 節は wonder(〜かしらと思う)の目的語=「〜かどうか」の名詞節。取り除くと I wonder. で不完全。', '(2) 名詞節なので、未来のことは will で表す。'], a: '(1) ① comes(彼が来たらすぐに会議を始めよう)(2) ② will come(彼は来週パーティーに来るだろうか)' }] },
      { h: '形容詞節の when にも注意', t: '名詞の後ろについて、その名詞を説明する when(関係副詞)の節も、副詞節ではありません。この場合も未来のことは will で表します。\n例:I\'m looking forward to the day when you will visit us.(あなたが訪ねてくれる日を楽しみにしています)\nまとめると、「現在形にする」のは【時・条件を表す副詞節】だけです。if・when を見たら、まず節のはたらき(副詞か名詞か)を確認する習慣をつけましょう。' }
    ],
    terms: [['節', 'S と V をふくむ語のかたまり'], ['副詞節', '文の中で「いつ・どんな条件で」などを表す節。取り除いても文が成り立つ'], ['名詞節', '文の中で S・O・C になる節。「〜かどうか」の if、「いつ〜か」の when など'], ['主節', '文の中心になる節(If it rains, I will stay home. の I will stay home)']],
    miss: ['If it will rain tomorrow, … と、条件の副詞節に will を入れてしまう。', '「〜かどうか」の if まで現在形にして、I don\'t know if he comes tomorrow. としてしまう。', 'unless(〜しない限り)の後ろに not を重ねて、二重否定にしてしまう。'],
    sum: ['時・条件の副詞節(when・if・before・until・as soon as など)は、未来でも現在形。', '「〜し終えたら」は現在完了で表す。', '「〜かどうか」の if、「いつ〜か」の when は名詞節なので will。', '見分けは、節を取り除いて文が成り立つかどうか。']
  };

  // ===== 助動詞 =====
  L.e_aux = {
    goal: '助動詞を使って「〜にちがいない」「〜したはずがない」「〜すべきだったのに」などの推量・後悔を表し、SVOO・SVOC の受動態も作れるようになる。',
    intro: '助動詞には、「〜できる」「〜しなければならない」のような意味のほかに、話し手が【どのくらい確信しているか】を表すはたらきがあります。「彼は疲れているにちがいない」「疲れているかもしれない」「疲れているはずがない」。英語では must・may・can\'t を使い分けます。さらに「助動詞 + have + 過去分詞」にすると、過去のことへの推量や後悔を表せます。',
    secs: [
      { h: '推量の助動詞と確信の強さ', t: '【must】〜にちがいない(ほぼ確実)\n例:He must be tired after the long trip.(長旅の後だから、彼は疲れているにちがいない)\n【should / ought to】(当然)〜のはずだ\n例:The bus should arrive soon.(バスはもうすぐ着くはずだ)\n【may / might】〜かもしれない(五分五分くらい。might のほうが少し弱い)\n例:It may rain this afternoon.(午後は雨が降るかもしれない)\n【can\'t / cannot】〜のはずがない(must の反対)\n例:That can\'t be true.(それが本当のはずがない)\n注意:must の反対は must not ではありません。must not は「〜してはいけない」(禁止)の意味になります。「〜のはずがない」は can\'t を使います。', fig: AUXSCALE },
      { h: '助動詞 + have + 過去分詞(過去への推量)', t: '過去のことを推量するときは、助動詞の後ろを【have + 過去分詞】にします。助動詞そのものは過去形にしなくてかまいません。\n【must have + 過去分詞】〜したにちがいない\n例:She must have left her umbrella on the train.(彼女は電車にかさを置き忘れたにちがいない)\n【may (might) have + 過去分詞】〜したかもしれない\n例:He may have missed the bus.(彼はバスに乗り遅れたのかもしれない)\n【can\'t (couldn\'t) have + 過去分詞】〜したはずがない\n例:Ken can\'t have said such a thing.(ケンがそんなことを言ったはずがない)' },
      { h: '後悔・非難を表す形', t: '「本当はこうすべきだったのに」と、過去の行動を後悔したり、相手を責めたりする表現です。\n【should have + 過去分詞】〜すべきだったのに(実際はしなかった)\n例:I should have studied harder.(もっと勉強しておくべきだった)\n【shouldn\'t have + 過去分詞】〜すべきではなかったのに(実際はした)\n例:You shouldn\'t have told her the secret.(彼女に秘密を話すべきではなかったのに)\n【need not (needn\'t) have + 過去分詞】〜する必要はなかったのに(実際はした)\n例:You needn\'t have brought an umbrella.(かさを持ってくる必要はなかったのに)\n【could have + 過去分詞】〜できたのに(実際はしなかった)/〜だったかもしれない\n例:You could have asked me for help.(私に助けを求めることもできたのに)',
        ex: [{ q: '日本語に合うように、( ) に適語を入れよう。\n「彼の家の電気が消えている。彼は出かけたにちがいない。」\nThe lights in his house are off. He ( ) ( ) ( ) out.', steps: ['「〜にちがいない」→ must。', '「出かけた」は過去のこと → must の後ろを have + 過去分詞にする。', 'go の過去分詞は gone。'], a: 'must have gone' }] },
      { h: 'よく出る助動詞の慣用表現', t: '【had better + 原形】〜したほうがよい(しないと困ったことになる、という強い忠告)。否定は had better not 〜。\n例:You had better see a doctor.(医者にみてもらったほうがいい)\n【would rather A (than B)】(B するより)むしろ A したい\n例:I would rather stay home than go out.(出かけるより家にいたい)\n【used to + 原形】以前はよく〜した/以前は〜だった(今はちがう)\n例:There used to be a big tree here.(以前はここに大きな木があった)\n【may well + 原形】〜するのももっともだ/たぶん〜だろう\n【may as well + 原形】〜したほうがよい(〜してもよい)' },
      { h: 'SVOO・SVOC の受動態', t: '【SVOO】は O が2つあるので、受動態も2通り作れます。\n能動態:He gave me a book.\n→ I was given a book by him.(私は彼から本をもらった)\n→ A book was given to me by him.(物を主語にするときは、人の前に to を置く)\n【SVOC】は O を主語にし、C はそのまま be + 過去分詞の後ろに残します。\n能動態:They named the baby Hana.\n→ The baby was named Hana.(その赤ちゃんはハナと名づけられた)\n【make O + 原形】(O に〜させる)の受動態は、原形が【to 不定詞】に変わります。\n能動態:The teacher made us wait.\n→ We were made to wait by the teacher.(私たちは先生に待たされた)\n助動詞をふくむ受動態は【助動詞 + be + 過去分詞】です。例:The work must be done by tomorrow.(その仕事は明日までに終えなければならない)',
        ex: [{ q: '受動態に書きかえよう。\n(1) They call the dog Max.\n(2) My mother made me clean my room.', steps: ['(1) SVOC。O(the dog)を主語にし、C(Max)は called の後ろに残す。', '(1) 主語 The dog は3人称単数・現在なので is called。', '(2) make O + 原形 の受動態。O(me)を主語の I にし、原形 clean は to clean にする。', '(2) 過去の文なので was made。'], a: '(1) The dog is called Max.(その犬はマックスと呼ばれている)(2) I was made to clean my room by my mother.(私は母に部屋を掃除させられた)' }] }
    ],
    terms: [['推量', '話し手が「たぶん〜だろう」と判断すること'], ['must have + 過去分詞', '〜したにちがいない'], ['can\'t have + 過去分詞', '〜したはずがない'], ['should have + 過去分詞', '〜すべきだったのに(しなかった)'], ['need not have + 過去分詞', '〜する必要はなかったのに(した)']],
    miss: ['「〜のはずがない」を must not で表してしまう(must not は禁止。正しくは can\'t)。', '過去の推量で、He musted go. や He must went. のように助動詞の後ろを過去形にしてしまう(正しくは must have gone)。', 'should have done を「〜したはずだ」とだけ覚えて、「すべきだったのに」の後悔の意味を落とす。', 'make O 原形 の受動態で、to を入れ忘れる(× We were made wait.)。'],
    sum: ['確信の強さは must > should > may・might > can\'t(否定)。', '過去への推量は 助動詞 + have + 過去分詞。', 'should have done=すべきだったのに、needn\'t have done=する必要はなかったのに。', 'SVOO の受動態は2通り、SVOC は C を後ろに残す。', 'be made to do のように、使役の原形は受動態で to 不定詞になる。']
  };

  // ===== 準動詞の基本 =====
  L.e_inf = {
    goal: '不定詞の3用法・動名詞・分詞の基本が分かり、動詞によって to 不定詞と動名詞を正しく使い分けられるようになる。',
    intro: '「to + 動詞の原形」(不定詞)、「動詞の ing 形」(動名詞・現在分詞)、「過去分詞」は、動詞からできているのに、文の中では名詞・形容詞・副詞のはたらきをします。まとめて【準動詞】といいます。どれを使うかは意味とイメージで決まります。大まかに言えば、to 不定詞は【これから先のこと】、動名詞は【すでにしていること・実際にしていること】です。',
    secs: [
      { h: '不定詞の3用法', t: '不定詞(to + 原形)は、文の中でのはたらきによって3つの用法に分かれます。\n【名詞的用法】「〜すること」。S・O・C になる。\n例:To learn a language takes time.(言語を学ぶことは時間がかかる)→ S\n例:I want to be a doctor.(私は医者になりたい)→ want の O\n【形容詞的用法】「〜するための・〜すべき」。前の名詞を説明する。\n例:I have a lot of homework to do.(やるべき宿題がたくさんある)\n例:I need something to drink.(何か飲み物がほしい)\n【副詞的用法】動詞や形容詞を説明する。「〜するために」(目的)、「〜して」(感情の原因)など。\n例:I went to the library to study.(勉強するために図書館へ行った)→ 目的\n例:I\'m glad to see you.(あなたに会えてうれしい)→ 感情の原因\n見分けるときは、「to 〜」を取り除いて、残った文で何が欠けるかを考えます。' },
      { h: 'to 不定詞をとる動詞・動名詞をとる動詞', t: '動詞によって、後ろ(目的語)に to 不定詞をとるか、動名詞をとるかが決まっています。\n【to 不定詞をとる動詞】これから先のことを表すものが多い。\nwant(〜したい)、hope(〜を望む)、wish、decide(〜しようと決める)、plan(〜するつもりだ)、promise(〜すると約束する)、expect(〜するつもりだ)、refuse(〜するのを断る)、manage(なんとか〜する)\n例:I decided to study abroad.(留学しようと決めた)\n【動名詞をとる動詞】すでにしていること・実際にしていることを表すものが多い。\nenjoy(〜を楽しむ)、finish(〜し終える)、avoid(〜を避ける)、mind(〜をいやがる)、give up(〜をやめる)、stop(〜するのをやめる)、practice(〜を練習する)、consider(〜しようかと考える)、deny(〜したことを否定する)、suggest(〜しようと提案する)\n例:I enjoyed talking with her.(彼女との会話を楽しんだ)\n× I enjoyed to talk with her. とは言いません。' },
      { h: 'to と ing で意味が変わる動詞', t: 'どちらもとれるけれど、意味が変わる動詞があります。「to=これから」「ing=すでに・実際に」のイメージで考えます。\n【remember to do】(これから)忘れずに〜する/【remember doing】(過去に)〜したことを覚えている\n例:Remember to lock the door.(忘れずにドアのかぎをかけてね)\n例:I remember locking the door.(ドアにかぎをかけたのを覚えている)\n【forget to do】〜し忘れる/【forget doing】〜したことを忘れる\n【try to do】〜しようとする/【try doing】ためしに〜してみる\n【regret to do】残念ながら〜する/【regret doing】〜したことを後悔する\n【stop doing】〜するのをやめる\n例:He stopped smoking.(彼はたばこを吸うのをやめた)\nなお He stopped to smoke. は「たばこを吸うために立ち止まった」の意味です。この to smoke は stop の目的語ではなく、目的を表す副詞的用法です。',
        ex: [{ q: '( ) 内の正しいほうを選び、和訳しよう。\n(1) Don\'t forget (to call / calling) me tonight.\n(2) I\'ll never forget (to visit / visiting) Kyoto with you last year.', steps: ['(1) tonight(今夜)=これから先のこと → to 不定詞。forget to do=〜し忘れる。', '(1) Don\'t forget to call=忘れずに電話してね。', '(2) last year(去年)=すでにしたこと → 動名詞。forget doing=〜したことを忘れる。'], a: '(1) to call(今夜、忘れずに私に電話してね)(2) visiting(去年あなたと京都を訪れたことは決して忘れないでしょう)' }] },
      { h: '分詞の基本:名詞を説明する', t: '分詞には【現在分詞(〜ing)】と【過去分詞】があり、どちらも形容詞のように名詞を説明できます。\n・現在分詞=「〜している」(能動):a sleeping baby(眠っている赤ちゃん)\n・過去分詞=「〜された」(受動):a broken window(割られた窓)\n分詞1語なら名詞の前、ほかの語句をともなうなら名詞の後ろに置きます。\n例:The boy playing tennis is my brother.(テニスをしている少年は私の弟だ)\n例:This is a car made in Japan.(これは日本で作られた車だ)\n能動か受動かは、【説明される名詞との関係】で決めます。窓は自分で割るのではなく「割られる」ので broken です。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) Look at the ( fall ) leaves.(落ちている葉)\n(2) English is a language ( speak ) all over the world.', steps: ['(1) 葉は自分で「落ちている」→ 能動 → 現在分詞 falling。1語なので名詞の前。', '(2) 言語は人に「話される」→ 受動 → 過去分詞 spoken。', '(2) all over the world をともなうので名詞 a language の後ろに置く。'], a: '(1) falling(落ち葉を見て)(2) spoken(英語は世界中で話されている言語だ)' }] }
    ],
    terms: [['準動詞', '不定詞・動名詞・分詞のこと。動詞からできて、名詞・形容詞・副詞のはたらきをする'], ['不定詞', 'to + 動詞の原形'], ['動名詞', '動詞の ing 形で「〜すること」の意味。名詞のはたらき'], ['現在分詞', '動詞の ing 形で「〜している」の意味。形容詞のはたらき'], ['過去分詞', '「〜された」の意味。受動態・完了形にも使う']],
    miss: ['enjoy to do、finish to do のように、動名詞をとる動詞に to 不定詞を続けてしまう。', 'remember to do と remember doing の意味を逆に覚える。', 'stop to do を「〜するのをやめる」と訳してしまう(正しくは「〜するために立ち止まる」)。', '分詞の能動・受動を、日本語の感覚だけで決めてしまう(説明される名詞との関係で決める)。'],
    sum: ['不定詞は 名詞的・形容詞的・副詞的 の3用法。', 'to 不定詞=これから先、動名詞=すでに・実際に、のイメージ。', 'want・decide・hope は to、enjoy・finish・avoid は ing。', 'remember・forget・try・regret は to と ing で意味が変わる。', '分詞は 〜ing=能動、過去分詞=受動。名詞との関係で決める。']
  };

  // ===== 関係詞 =====
  L.e_h4 = {
    goal: '関係副詞(where・when・why・how)と関係代名詞 what を正しく使い分け、非制限用法・複合関係詞の意味もとれるようになる。',
    intro: '関係代名詞(who・which・that)は、名詞を後ろから説明する節を作りました。【関係副詞】も同じように名詞を説明しますが、使うのは「場所・時・理由」などを表す名詞のときです。どちらを使うかは、後ろの文が【完全か、欠けているか】で決まります。この判定ができれば、関係詞の問題はほとんど解けます。',
    secs: [
      { h: '関係副詞 where・when・why・how', t: '関係副詞は、先行詞(説明される名詞)の種類で使い分けます。\n【where】場所:This is the house where I was born.(これは私が生まれた家だ)\n【when】時:I remember the day when we first met.(私たちが初めて会った日を覚えている)\n【why】理由(先行詞は the reason):That is the reason why I was late.(それが私が遅れた理由だ)\n【how】方法:This is how he solved the problem.(このようにして彼はその問題を解いた)\nhow は先行詞 the way と一緒には使いません。the way か how の【どちらか一方】だけを使います。\n○ This is the way he solved the problem. ○ This is how he solved the problem. × This is the way how he solved the problem.' },
      { h: '関係副詞か関係代名詞か(最重要の判定法)', t: '先行詞が場所だからといって、いつも where になるわけではありません。決め手は【関係詞の後ろの文】です。\n・後ろが【完全な文】(S・V・O などが全部そろっている)→ 関係副詞\n・後ろが【不完全な文】(S や O が欠けている)→ 関係代名詞\n例:This is the town where I lived ten years ago.\n→ I lived ten years ago は、live が自動詞なのでこれで完全な文 → where\n例:This is the town which I visited ten years ago.\n→ I visited ten years ago は、visit(〜を訪れる)の O が欠けている → which\n関係副詞は「前置詞 + which」に言いかえられます。where = in which(at which)、when = on which(in which)など。\n例:the house where I was born = the house in which I was born',
        ex: [{ q: '( ) に where か which を入れよう。\n(1) Kyoto is a city ( ) many people visit every year.\n(2) Kyoto is a city ( ) you can see many old temples.', steps: ['(1) 後ろ:many people visit every year。visit は他動詞なのに O がない → 不完全 → 関係代名詞。', '(1) 先行詞 a city は物なので which。', '(2) 後ろ:you can see many old temples。S・V・O がそろっている → 完全 → 関係副詞。', '(2) 先行詞は場所なので where。'], a: '(1) which(京都は毎年多くの人が訪れる都市だ)(2) where(京都は古い寺をたくさん見られる都市だ)' }] },
      { h: '先行詞をふくむ what', t: '【what】は「〜すること・〜するもの」という意味で、先行詞をふくんだ関係代名詞です。what = the thing(s) which と考えます。だから what の前に先行詞はつけません。\n例:What he said was true.(彼が言ったことは本当だった)→ What he said が S\n例:This is what I wanted.(これが私のほしかったものだ)→ what I wanted が C\nwhat の後ろも、関係代名詞なので【不完全な文】になります(said・wanted の O が欠けている)。\n慣用表現:what is called(いわゆる)、what S is(今の S の姿)、what is more(さらに)\n例:My parents made me what I am.(両親のおかげで今の私がある)' },
      { h: '非制限用法(コンマのある関係詞)', t: '関係詞の前に【コンマ】をつけると、先行詞についての情報を「ちなみに〜」と付け足す言い方になります。これを【非制限用法】といいます。\n例:I have a brother, who lives in Osaka.(私には兄が1人いて、その兄は大阪に住んでいる)\n例:I have a brother who lives in Osaka.(私には大阪に住んでいる兄がいる)→ ほかにも兄弟がいるかもしれない\n注意点:\n・非制限用法では【that は使えません】。\n・which は、前の文の内容全体を先行詞にすることができます。\n例:He said he was sick, which was not true.(彼は病気だと言ったが、それは本当ではなかった)\n・where・when も非制限用法で使えます。例:I went to Nara, where I saw many deer.(奈良へ行き、そこでたくさんのシカを見た)' },
      { h: '複合関係詞(〜ever)', t: '関係詞に ever をつけた形を【複合関係詞】といいます。2つの意味があります。\n【名詞のはたらき】whoever=〜する人はだれでも、whatever=〜するものは何でも\n例:Whoever comes will be welcome.(来る人はだれでも歓迎される)\n例:You can take whatever you like.(好きなものは何でも持っていっていいよ)\n【譲歩の副詞節】「たとえ〜でも」=no matter + 疑問詞\n例:Whatever happens, I will support you.(たとえ何が起きても、あなたを支える)= No matter what happens, …\n例:Wherever you go, I will follow you.(どこへ行こうとも、ついていく)\n【however + 形容詞・副詞 + S + V】どんなに〜しても\n例:However hard you try, you can\'t finish it in a day.(どんなに一生けんめいやっても、1日では終えられない)\nhowever の直後に形容詞・副詞を置く語順に注意します(× However you try hard)。',
        ex: [{ q: '和訳しよう。\nHowever busy she is, she reads the newspaper every morning.', steps: ['However + 形容詞(busy)+ S + V → 「どんなに〜でも」という譲歩。', 'However busy she is=彼女がどんなに忙しくても。', '主節:she reads the newspaper every morning=毎朝新聞を読む。'], a: '彼女はどんなに忙しくても、毎朝新聞を読む。' }] }
    ],
    terms: [['先行詞', '関係詞の節によって説明される名詞'], ['関係副詞', 'where・when・why・how。後ろに完全な文がくる'], ['関係代名詞 what', '「〜すること・もの」。先行詞をふくむ'], ['非制限用法', 'コンマ + 関係詞。先行詞に情報を付け足す。that は使えない'], ['複合関係詞', 'whoever・whatever・however など。「〜は何でも」や「たとえ〜でも」の意味']],
    miss: ['先行詞が場所というだけで where を選んでしまう(後ろが不完全なら which)。', 'the way how と、the way と how を一緒に使ってしまう。', 'what の前に先行詞を置いて、the thing what としてしまう。', '非制限用法(コンマの後)に that を使ってしまう。'],
    sum: ['場所 where、時 when、理由 why、方法 how(the way とは併用しない)。', '後ろが完全な文なら関係副詞、不完全なら関係代名詞。', 'what=the thing(s) which。前に先行詞を置かない。', 'コンマ + 関係詞は付け足しの情報。that は不可、which は前の文全体も受ける。', 'however + 形容詞・副詞 + S + V=どんなに〜しても。']
  };

  // ===== 分詞構文 =====
  L.e_h3 = {
    goal: '分詞構文を作ったり訳したりでき、能動(〜ing)と受動(過去分詞)を主語との関係で正しく選べるようになる。',
    intro: '「駅まで歩いていたとき、私はケンに会った」は、When I was walking to the station, I met Ken. です。これを、Walking to the station, I met Ken. と短くした形が【分詞構文】です。接続詞と主語を省いて、分詞で文をつなぐので、文がひきしまります。英文を読むときは、省かれた接続詞を自分で補って意味を考えます。',
    secs: [
      { h: '分詞構文の作り方', t: '接続詞のある文から、次の手順で分詞構文を作ります。\n① 接続詞を消す。\n② 主節と主語が同じなら、主語を消す。\n③ 動詞を【〜ing(現在分詞)】にする。\n例:When I was walking to the station, I met Ken.\n→ ① When を消す ② I を消す ③ was walking を Walking にする(be動詞は being になり、省かれる)\n→ Walking to the station, I met Ken.\n例:Because she felt tired, she went to bed early.\n→ Feeling tired, she went to bed early.(疲れていたので、彼女は早く寝た)' },
      { h: '分詞構文の意味', t: '接続詞を消しているので、意味は文脈から判断します。主なものは次の5つです。\n【時】〜するとき・〜していると:Opening the door, I found a cat.(ドアを開けると、ねこがいた)\n【理由】〜なので:Having no money, I couldn\'t buy it.(お金がなかったので、それを買えなかった)\n【付帯状況】〜しながら:He watched TV, eating snacks.(彼はおやつを食べながらテレビを見た)\n【条件】〜すれば:Turning left, you will find the post office.(左に曲がれば、郵便局が見つかります)\n【譲歩】〜だけれども:Admitting what you say, I still disagree.(あなたの言うことは認めるが、やはり賛成できない)\n入試や読解では、時・理由・付帯状況が特によく出ます。迷ったら「〜して、」とゆるくつないで訳し、文脈に合う接続詞を考えます。' },
      { h: '受動・完了・否定の分詞構文', t: '【受動】主語が「〜される」側なら、Being + 過去分詞。Being はふつう省略され、【過去分詞】で始まります。\n例:Seen from the hill, the town looks beautiful.(丘から見ると、その町は美しく見える)→ 町は「見られる」側\n【完了】主節よりも前のことなら【Having + 過去分詞】。\n例:Having finished my homework, I went out.(宿題を終えてから、外出した)\n【否定】not や never を分詞の【直前】に置きます。\n例:Not knowing what to say, I kept silent.(何と言えばよいか分からなかったので、黙っていた)\n能動か受動かは、【分詞構文の意味上の主語(主節の主語)】との関係で決めます。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n( Write ) in easy English, this book is good for beginners.', steps: ['主節の主語は this book。分詞構文の意味上の主語も this book。', '本は自分で書くのではなく「書かれる」側 → 受動。', '受動の分詞構文は (Being) + 過去分詞。write の過去分詞は written。'], a: 'Written(やさしい英語で書かれているので、この本は初心者に向いている)' }] },
      { h: '独立分詞構文と慣用表現', t: '分詞構文の主語が主節の主語と【ちがう】ときは、主語を消さずに分詞の前に残します。これを【独立分詞構文】といいます。\n例:It being fine, we went hiking.(晴れていたので、私たちはハイキングに行った)→ 主語 It と we がちがう\n主語がばくぜんとした「人一般」のときは、主語を書かずに慣用表現として使います。\n【generally speaking】一般的に言えば/【frankly speaking】率直に言えば/【judging from 〜】〜から判断すると/【considering 〜】〜を考えると/【speaking of 〜】〜と言えば' },
      { h: '付帯状況の with と have O 過去分詞', t: '【with + O + 分詞】は「O を〜した状態で」という付帯状況を表します。O と分詞の関係で、〜ing か過去分詞かを決めます。\n例:He was sitting with his eyes closed.(彼は目を閉じて座っていた)→ 目は「閉じられる」側なので過去分詞\n例:She came in with her dog following her.(彼女は犬をうしろにつれて入ってきた)→ 犬が「ついてくる」ので〜ing\n【have + O + 過去分詞】は「O を〜してもらう・〜される」の意味です。\n例:I had my bike repaired.(自転車を修理してもらった)→ 自転車は「修理される」側\n例:I had my wallet stolen.(財布を盗まれた)',
        ex: [{ q: '分詞構文を使って書きかえよう。\nAfter I had finished my work, I went home.', steps: ['接続詞 After を消す。主節の主語も I なので、I も消す。', '仕事を終えたのは、家に帰るより前のこと → 完了の分詞構文 Having + 過去分詞。', 'had finished → Having finished。'], a: 'Having finished my work, I went home.(仕事を終えて、私は家に帰った)' }] }
    ],
    terms: [['分詞構文', '接続詞と主語を省き、分詞で始めて文をつなぐ形'], ['意味上の主語', '分詞の動作をする(される)人・もの。ふつうは主節の主語'], ['付帯状況', '「〜しながら」「〜した状態で」の意味'], ['独立分詞構文', '分詞の前に、主節とちがう主語を残した分詞構文']],
    miss: ['Seen from the hill を Seeing にしてしまう(主語の町は「見られる」側)。', '主節より前のことなのに、Having + 過去分詞にせず、ただの〜ing にしてしまう。', 'not の位置をまちがえて、Knowing not … としてしまう(not は分詞の直前)。', '主語がちがうのに主語を消してしまい、意味が通らない文になる(独立分詞構文にする)。'],
    sum: ['接続詞を消す → 同じ主語を消す → 動詞を〜ing に。', '意味は 時・理由・付帯状況・条件・譲歩。文脈で決める。', '受動は過去分詞、主節より前は Having + 過去分詞、否定は Not を前に。', 'with + O + 分詞、have + O + 過去分詞 も「O との関係」で形を決める。']
  };

  // ===== 比較 =====
  L.e_comp = {
    goal: '倍数表現・the 比較級, the 比較級・no more than などの比較の慣用表現を、もとの比較の意味から理解して使えるようになる。',
    intro: '比較の基本は、as 〜 as(同じくらい)、比較級 + than(〜より)、the + 最上級(いちばん)の3つです。高校では、これに「〜の3倍」「〜すればするほど」「たった〜」などの表現が加わります。丸暗記すると混乱しがちですが、【もとの比較の意味】から考えると、理由ごと理解できます。',
    secs: [
      { h: '倍数表現', t: '「A は B の X 倍〜だ」は、【X times as 〜 as B】で表します。\n例:This room is three times as large as that one.(この部屋はあの部屋の3倍の広さだ)\n2倍は【twice】、半分は【half】を使います。\n例:My brother has twice as many books as I do.(兄は私の2倍の本を持っている)\n例:This box is half as heavy as that one.(この箱はあの箱の半分の重さだ)\n名詞を使って【X times the 名詞 of B】と書くこともできます。\n例:This room is three times the size of that one.(この部屋はあの部屋の3倍の広さだ)\n3倍以上なら、X times + 比較級 + than も使えます。例:three times larger than' },
      { h: 'the 比較級, the 比較級 と比較級の強調', t: '【the 比較級 + S + V, the 比較級 + S + V】で、「〜すればするほど、ますます…」の意味です。\n例:The more you practice, the better you become.(練習すればするほど、上手になる)\n例:The older he grew, the wiser he became.(彼は年をとるにつれて、賢くなった)\n比較級を強めて「ずっと〜」と言うときは、【much・far・even・still・a lot】を比較級の前に置きます。very は使いません。\n例:This book is much more interesting than that one.(この本はあの本よりずっとおもしろい)\n× very more interesting' },
      { h: '最上級の意味を表す比較級・原級', t: '「富士山は日本でいちばん高い山だ」は、最上級以外の形でも表せます。\n① Mt. Fuji is the highest mountain in Japan.(最上級)\n② Mt. Fuji is higher than any other mountain in Japan.(比較級 + than any other + 【単数名詞】)\n③ No other mountain in Japan is higher than Mt. Fuji.(No other + 単数名詞 + 比較級 than)\n④ No other mountain in Japan is as high as Mt. Fuji.(No other + 単数名詞 + as 〜 as)\nany other の後ろは単数名詞になることに注意します(× any other mountains)。\nまた、【as 〜 as possible】(= as 〜 as S can)は「できるだけ〜」です。\n例:Please come as soon as possible.(できるだけ早く来てください)',
        ex: [{ q: '同じ意味になるように ( ) に適語を入れよう。\nTom is the tallest boy in his class.\n= Tom is ( ) than ( ) ( ) boy in his class.', steps: ['最上級の文を「比較級 + than any other + 単数名詞」で書きかえる。', 'tall の比較級は taller。', 'than の後ろは any other、名詞は単数の boy のまま。'], a: 'taller / any / other(トムはクラスのほかのどの男子よりも背が高い)' }] },
      { h: 'no more than / no less than などの慣用表現', t: '【no + 比較級】の no は、「差がゼロ」という意味です。そこに話し手の気持ち(少ない・多い)が加わります。\n【no more than 〜】たった〜(= only)。「〜より多いことはまったくない」→ 少ないという気持ち。\n例:I have no more than 500 yen.(500円しか持っていない)\n【no less than 〜】〜も(= as much as / as many as)。「〜より少ないことはまったくない」→ 多いという気持ち。\n例:He has no less than 500 books.(彼は500冊も本を持っている)\nこれに対して not を使うと、単なる範囲を表します。\n【not more than 〜】多くても〜(= at most)/【not less than 〜】少なくとも〜(= at least)\nほかによく出るもの:【no longer】もはや〜ない/【A is no more B than C is D】A が B でないのは、C が D でないのと同じだ(クジラの構文)\n例:A whale is no more a fish than a horse is.(馬が魚でないのと同じように、クジラも魚ではない)',
        ex: [{ q: '和訳しよう。\n(1) It took no more than ten minutes to get there.\n(2) No less than 3,000 people came to the concert.', steps: ['(1) no more than=only(たった〜)。少ないという気持ち。', '(1) to get there=そこに着くのに。It took 〜 to …=…するのに〜かかった。', '(2) no less than=as many as(〜も)。多いという気持ち。'], a: '(1) そこに着くのに、たった10分しかかからなかった。(2) 3,000人もの人がそのコンサートに来た。' }] }
    ],
    terms: [['原級', '比較の変化をしていない、もとの形(tall)'], ['比較級', '2つを比べる形(taller、more 〜)'], ['最上級', '3つ以上の中でいちばんを表す形(tallest、most 〜)'], ['倍数表現', 'X times as 〜 as。2倍は twice、半分は half'], ['no more than', 'たった〜(= only)']],
    miss: ['three times as large as を、three times larger as のように混ぜてしまう。', '比較級を very で強めてしまう(正しくは much・far・even)。', 'than any other の後ろを複数名詞にしてしまう。', 'no more than(たった)と not more than(多くても)を同じ意味だと思ってしまう。'],
    sum: ['倍数は X times as 〜 as。2倍 twice、半分 half。', 'the 比較級, the 比較級=〜すればするほど…。', '比較級の強調は much・far・even(very は不可)。', '最上級は 比較級 + than any other + 単数名詞 などでも表せる。', 'no more than=only、no less than=as many(much) as。']
  };

  // ===== 仮定法 =====
  L.e_h2 = {
    goal: '仮定法過去・仮定法過去完了を使い分け、I wish・as if・Without 〜・if の省略など、if を使わない仮定法も読み書きできるようになる。',
    intro: '「もし私が鳥だったら、あなたのところへ飛んでいけるのに」。現実にはありえないことを想像して言うとき、英語では【時制を1つ過去にずらす】というルールを使います。今のことなのに過去形、過去のことなのに過去完了形。この「ずらし」によって、「これは現実ではありませんよ」という合図を出すのが【仮定法】です。',
    secs: [
      { h: '仮定法過去:今の事実に反する想像', t: '【If + S + 動詞の過去形, S + would(could・might) + 原形】\n「(今)もし〜なら、…だろうに」という意味です。形は過去形ですが、内容は【今】のことです。\n例:If I were a bird, I could fly to you.(もし私が鳥なら、あなたのところへ飛んでいけるのに)\n例:If I had more money, I would buy a new computer.(もっとお金があれば、新しいパソコンを買うのに)\n→ 事実は「お金がないので買えない」。\nbe動詞は、主語が I や he でも【were】を使うのが基本です(話し言葉では was も使われます)。' },
      { h: '仮定法過去完了:過去の事実に反する想像', t: '【If + S + had + 過去分詞, S + would(could・might) + have + 過去分詞】\n「(あのとき)もし〜だったら、…だっただろうに」という意味です。\n例:If I had studied harder, I would have passed the exam.(もっと勉強していたら、試験に合格しただろうに)\n→ 事実は「勉強しなかったので不合格だった」。\nまた、「過去に〜していたら、今は…だろうに」と、if 節が過去、主節が今のことを表す【混合型】もあります。\n例:If I had taken the medicine last night, I would feel better now.(昨夜薬を飲んでいたら、今は気分がよいだろうに)\n→ if 節は過去完了、主節は would + 原形。now があることが目印です。',
        ex: [{ q: '( ) に入る正しい形を選ぼう。\nIf he had left home earlier, he ( ) the train.\n① would catch ② would have caught ③ will catch ④ caught', steps: ['if 節が had left(had + 過去分詞)→ 過去の事実に反する仮定(仮定法過去完了)。', '主節も過去のこと(電車に間に合ったかどうか)で、now などの語はない。', '主節は would + have + 過去分詞。'], a: '② would have caught(もっと早く家を出ていたら、彼はその電車に間に合っただろうに)' }] },
      { h: 'I wish・as if・It is time', t: '【I wish + 仮定法】「〜ならいいのに」(実現しない願望)\n・今のこと → 過去形:I wish I could speak French.(フランス語が話せたらいいのに)\n・過去のこと → 過去完了:I wish I had known the truth.(真実を知っていたらよかったのに)\n【as if + 仮定法】「まるで〜であるかのように」\n例:He talks as if he knew everything.(彼はまるで何でも知っているかのように話す)\n例:She looked as if she had seen a ghost.(彼女はまるで幽霊を見たかのような顔をしていた)\n【It is time + S + 過去形】「もう〜してもよいころだ」\n例:It is time you went to bed.(もう寝る時間ですよ)' },
      { h: 'if を使わない仮定法', t: '【Without 〜 / But for 〜】〜がなければ(なかったら)\n例:Without your help, I would have failed.(あなたの助けがなかったら、失敗していただろう)\n= If it had not been for your help, …\n今のことなら If it were not for 〜(〜がなければ)を使います。\n例:If it were not for water, nothing could live.(水がなければ、何も生きられないだろう)\n【if の省略と倒置】if を省くと、were・had・should が主語の前に出ます(疑問文の語順)。\n例:Were I you, I would accept the offer.(= If I were you, …)(私があなたなら、その申し出を受けるだろう)\n例:Had I known it, I would have told you.(= If I had known it, …)(それを知っていたら、あなたに言っていただろう)\n【If S should 〜 / If S were to 〜】万一〜なら/仮に〜なら(未来について、可能性が低い想像)\n例:If it should rain tomorrow, the game will be put off.(万一明日雨が降れば、試合は延期される)\n※ should の文は主節に will や命令文が来ることもあります。',
        ex: [{ q: 'if を使って書きかえよう。\nWithout his advice, I could not have succeeded.', steps: ['主節が could not have succeeded(have + 過去分詞)→ 過去のことへの仮定。', '過去の「〜がなかったら」は If it had not been for 〜。', 'Without his advice を If it had not been for his advice にする。'], a: 'If it had not been for his advice, I could not have succeeded.(彼の助言がなかったら、私は成功できなかっただろう)' }] }
    ],
    terms: [['仮定法過去', 'If + 過去形, would + 原形。今の事実に反する想像'], ['仮定法過去完了', 'If + had + 過去分詞, would have + 過去分詞。過去の事実に反する想像'], ['混合型', 'if 節は過去完了、主節は would + 原形。過去の仮定と今の結果'], ['倒置', 'if を省いたとき、Were・Had・Should を主語の前に出す形'], ['直説法', '現実のことをそのまま述べる、ふつうの言い方']],
    miss: ['仮定法過去の文を「過去のこと」と訳してしまう(内容は今のこと)。', 'If I had studied … I would pass the exam. のように、if 節と主節の時をずらしてしまう(混合型は now などの目印があるときだけ)。', 'Without の後ろに文(S + V)を続けてしまう(Without の後ろは名詞)。', 'if を省いたのに倒置を忘れて、I had known it, … としてしまう。'],
    sum: ['仮定法は「時制を1つ過去にずらす」=現実ではないという合図。', '今への仮定は過去形、過去への仮定は過去完了。', 'I wish・as if の後ろも、今なら過去形、過去なら過去完了。', 'Without 〜 / But for 〜 / If it were not for 〜 / If it had not been for 〜。', 'if を省くと Were・Had・Should が文頭に出る。']
  };

  // ===== 強調・倒置・省略・挿入・話法 =====
  L.e_emph = {
    goal: '強調構文・倒置・省略・挿入を見抜いて正しく訳し、直接話法と間接話法を書きかえられるようになる。',
    intro: '英語の文は、ふつうは S + V の語順です。ところが、言いたいことを目立たせたいときや、くり返しを避けたいときには、語順を入れかえたり、語を省いたりします。こうした「ふつうでない形」に出会うと、文の骨組みが見えにくくなります。この単元では、その形の決まりを知り、もとのふつうの文に戻して読めるようにします。',
    secs: [
      { h: '強調構文 It is 〜 that …', t: '文の中の1つの語句を目立たせたいとき、【It is(was)+ 強調したい語句 + that …】の形にします。「…なのは〜だ」と訳します。\nもとの文:Ken broke the window yesterday.\n→ It was Ken that broke the window yesterday.(昨日窓を割ったのはケンだった)\n→ It was the window that Ken broke yesterday.(昨日ケンが割ったのは窓だった)\n→ It was yesterday that Ken broke the window.(ケンが窓を割ったのは昨日だった)\n強調する語句が人なら that の代わりに who、物なら which を使うこともあります。\n【見分け方】It is(was)と that を取り除いてみます。残りがそのまま完全な文になれば強調構文です。\n例:It is true that he broke the window. → true he broke the window は文にならない → これは強調構文ではなく、It が that 以下を指す【形式主語】の文です。',
        ex: [{ q: '次の文は強調構文か、形式主語の文か。和訳もしよう。\n(1) It was in this park that I first met her.\n(2) It is important that we keep our promises.', steps: ['(1) It was と that を取り除く → in this park I first met her → I first met her in this park. という完全な文になる → 強調構文。', '(1) 強調されているのは in this park。「…したのは〜だ」と訳す。', '(2) It is と that を取り除く → important we keep our promises → 文にならない → 形式主語。', '(2) It は that 以下(約束を守ること)を指す。'], a: '(1) 強調構文:私が初めて彼女に会ったのは、この公園だった。(2) 形式主語:約束を守ることは大切だ。' }] },
      { h: '倒置:否定語が文頭に来ると疑問文の語順', t: '【Never・Little・Hardly・Not only・Only + 副詞(句)】などの否定・限定の語句を文頭に出して強調すると、その後ろは【疑問文と同じ語順】(助動詞・be動詞 + S)になります。\n例:I have never seen such a beautiful sunset.\n→ Never have I seen such a beautiful sunset.(こんなに美しい夕日は見たことがない)\n例:I little dreamed that I would win.\n→ Little did I dream that I would win.(自分が勝つとは夢にも思わなかった)→ 一般動詞は do・does・did を使う\n例:Not only did he sing, but he also danced.(彼は歌っただけでなく、踊りもした)\n例:Only then did I realize my mistake.(そのとき初めて、自分のまちがいに気づいた)\n【No sooner had S + 過去分詞 than 〜】【Hardly(Scarcely)had S + 過去分詞 when(before)〜】は「…するとすぐに〜」の意味です。\n例:No sooner had I left home than it began to rain.(家を出たとたんに雨が降りだした)\nほかに、【So + 助動詞 + S】(S もそうだ)、【Neither(Nor)+ 助動詞 + S】(S もそうではない)も倒置です。\n例:"I like cats." "So do I."(「ねこが好きです」「私もです」)' },
      { h: '省略と挿入', t: '【省略】くり返しになる語や、言わなくても分かる語は省かれます。\n・時・条件などの副詞節で、主語が主節と同じとき、【S + be動詞】がよく省かれます。\n例:When (I was) young, I lived in Kobe.(若いころ、神戸に住んでいた)\n例:Fill in this form if (it is) necessary.(必要なら、この用紙に記入してください)\n・前に出た動詞のくり返しも省かれます。例:You can go if you want to (go).(行きたいなら行っていいよ)\n【挿入】文の途中に、コンマやダッシュではさんで語句が入ることがあります。\n例:He is, I think, the best player on the team.(彼は、私が思うに、チームでいちばんの選手だ)\n挿入部分をいったんかっこでくくって外すと、文の骨組み(He is the best player)が見えます。' },
      { h: '話法の転換', t: '人の言葉を引用符(" ")でそのまま伝えるのが【直接話法】、自分の言葉に直して伝えるのが【間接話法】です。間接話法にするときは、次の3つを変えます。\n① 【代名詞】を、伝える人の立場に合わせる(I → he・she など)。\n② 【時制】を、伝える動詞が過去なら1つ過去にずらす(現在 → 過去、過去・現在完了 → 過去完了、will → would)。\n③ 【時・場所の語】を変える:now → then、today → that day、tomorrow → the next day、yesterday → the day before、ago → before、here → there、this → that\n例:He said to me, "I will help you tomorrow."\n→ He told me (that) he would help me the next day.(彼は翌日私を手伝うと言った)\n疑問文は【ask + 疑問詞(または if)+ S + V】、命令文は【tell + 人 + to 不定詞】にします。\n例:She said to me, "Where do you live?" → She asked me where I lived.\n例:He said to me, "Open the window." → He told me to open the window.',
        ex: [{ q: '間接話法に書きかえよう。\nMy mother said to me, "Are you hungry now?"', steps: ['疑問詞のない疑問文 → asked me if(whether)〜。', '代名詞:you は「私」のこと → I。', '時制:said が過去なので are → was。now → then。', '語順は「if + S + V」(疑問文の語順にしない)。'], a: 'My mother asked me if I was hungry then.(母は私に、そのときおなかがすいているかとたずねた)' }] }
    ],
    terms: [['強調構文', 'It is 〜 that …。〜の部分を目立たせる'], ['形式主語', 'It を仮の主語にして、本当の主語(that 節・to 不定詞)を後ろに置く形'], ['倒置', '強調などのために、ふつうの語順(S + V)を入れかえること'], ['直接話法', '人の言葉を " " でそのまま伝える方法'], ['間接話法', '人の言葉を、伝える人の立場から言い直して伝える方法']],
    miss: ['強調構文と形式主語の文を区別せずに訳してしまう(It is と that を外して確かめる)。', 'Never I have seen … のように、否定語を文頭に出したのに倒置を忘れる。', '間接話法の疑問文で、She asked me where did I live. と疑問文の語順を残してしまう。', '間接話法で、tomorrow や here をそのまま残してしまう。'],
    sum: ['強調構文は、It is と that を外すと完全な文に戻る。', '否定語・Only 〜 が文頭に来たら、疑問文の語順(倒置)。', '副詞節の S + be動詞 は省略されやすい。挿入はかっこでくくって外す。', '間接話法は 代名詞・時制・時と場所の語 の3つを変える。', '疑問文は ask + if/疑問詞 + S + V、命令文は tell + 人 + to 〜。']
  };

  // ===== 入試レベル =====
  L.ex_eng = {
    goal: '時制・仮定法・関係詞・準動詞・比較が組み合わさった入試の文法問題を、「骨格 → 空所の働き → 文法項目」の順で解けるようになる。',
    intro: '入試の文法・語法問題は、1問の中に複数の文法事項が重なっていることがよくあります。空所の前後の2〜3語だけを見て選ぶと、ひっかけの選択肢にだまされます。どんな問題でも、【文全体の骨組み(S と V)を先に見つける】ことから始めれば、正解の根拠がはっきりします。この単元では、高校で学ぶ文法の要点を総復習しながら、入試での解き方の型を身につけます。',
    secs: [
      { h: '解き方の型(4ステップ)', t: '① 【文の骨格を見つける】主節の S と V に印をつけます。接続詞・関係詞のかたまりはかっこでくくります。\n② 【空所の働きを決める】空所が S・V・O・C・M のどれにあたるか、品詞は何か(名詞・形容詞・副詞・動詞)を決めます。\n③ 【文法項目を特定する】選択肢を見て、何がテーマの問題か(時制・仮定法・関係詞・準動詞・比較・語法)を判断します。\n④ 【根拠となる語を探す】時を表す語、if、先行詞、主語との関係など、答えを決める「目印」を文中から見つけ、それを根拠に選びます。\n選んだら、最後に全文を訳して意味が通るか確かめます。' },
      { h: '時制・仮定法の目印', t: '時制や仮定法の問題では、次の目印が決め手になります。\n・by the time + 過去 / when + 過去 → 過去完了(had + 過去分詞)\n・by + 未来の時点 / by the time + 現在形 → 未来完了(will have + 過去分詞)\n・since 〜 / for 〜 + 今まで → 現在完了\n・時・条件の副詞節(if・when・as soon as)→ 未来でも現在形\n・主節に would have + 過去分詞 → if 節は had + 過去分詞\n・now / today が主節にあり、if 節が過去完了 → 混合型(would + 原形)\n・文頭の Were・Had・Should → if が省略された仮定法\n【提案・要求の that 節】suggest・insist・demand・propose・recommend などの後ろの that 節では、動詞は【(should +)原形】になります。主語が3人称単数でも -s をつけません。\n例:I suggested that he see a doctor.(私は彼に医者にみてもらうよう提案した)',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nThe doctor recommended that my father ( ) smoking.\n① stops ② stop ③ stopped ④ will stop', steps: ['骨格:S=The doctor、V=recommended。that 以下は recommended の O。', 'recommend(〜を勧める)は提案・要求の動詞 → that 節の動詞は (should +) 原形。', '主語 my father は3人称単数だが、原形なので -s はつかない。', 'stopped(過去形)や stops は、時制の一致や3単現にひっかけた選択肢。'], a: '② stop(医者は父に禁煙するよう勧めた)' }] },
      { h: '関係詞・準動詞の目印', t: '【関係詞】後ろの文が完全か不完全かで決めます。\n・不完全(S・O が欠ける)→ 関係代名詞(who・which・that・what)\n・完全 → 関係副詞(where・when・why)、または接続詞 that\n・先行詞がない → what\n・コンマの後 → that は不可\n【連鎖関係代名詞】関係代名詞の後ろに I think・I believe などがはさまる形にも注意します。\n例:The man who I thought was honest deceived me.(私が正直だと思っていた男は、私をだました)→ I thought をかっこに入れると、who was honest となり、who は was の主語(主格)。\n【準動詞】\n・動詞の語法:want・decide は to、enjoy・avoid は ing\n・分詞・分詞構文:主語(説明される名詞)が「する」側なら〜ing、「される」側なら過去分詞\n・使役:make・let・have + O + 原形、get + O + to 不定詞',
        ex: [{ q: '( ) に入る最も適切なものを選ぼう。\nThe language ( ) in this country is similar to Spanish.\n① speaking ② spoken ③ is spoken ④ to speak', steps: ['骨格:S=The language、V=is(similar)。動詞はすでにあるので、③ is spoken を入れると V が2つになり不可。', '空所以下 ( ) in this country は The language を後ろから説明する形容詞のかたまり → 分詞。', '言語は人に「話される」側 → 受動 → 過去分詞。'], a: '② spoken(この国で話されている言語は、スペイン語に似ている)' }] },
      { h: '比較・語法の目印', t: '【比較】\n・as 〜 as の間は原級、than の前は比較級\n・比較級の強調は much・far・even(very は不可)\n・than any other + 単数名詞\n・倍数は X times as 〜 as\n・the 比較級, the 比較級(後半にも the が必要)\n【まぎらわしい動詞の語法】\n・自動詞と他動詞:lie(横になる)/lay(〜を置く)、rise(上がる)/raise(〜を上げる)\n・前置詞が不要な他動詞:discuss、marry、enter、reach、approach\n・「貸す・借りる」:lend(貸す)、borrow(借りる)、rent(有料で貸し借りする)\n・「言う」:say(言葉を言う)、tell + 人(人に伝える)、talk・speak(話す。talk to 人)\n最後に必ず全文を訳して、意味が自然かを確かめましょう。' }
    ],
    terms: [['骨格', '文の中心になる主節の S と V'], ['空所の働き', '空所が文の中で S・V・O・C・M のどれにあたるか'], ['提案・要求の that 節', 'suggest・insist などの後ろの that 節。動詞は (should +) 原形'], ['連鎖関係代名詞', '関係代名詞の後ろに I think などがはさまる形']],
    miss: ['空所の前後だけを見て、文の中に V がすでにあるのにもう1つ V を入れてしまう。', 'suggest that he sees のように、提案の that 節で -s をつけてしまう。', '連鎖関係代名詞で、I thought の目的語だと考えて whom を選んでしまう。', '答えを選んだあとに全文を訳して確かめず、意味の通らない文のままにする。'],
    sum: ['まず主節の S と V を見つけ、かたまりをかっこでくくる。', '空所の働き(品詞)→ 文法項目 → 根拠の語 の順に考える。', '時制は「基準の時点」、関係詞は「後ろの文が完全か」、分詞は「能動か受動か」が決め手。', '提案・要求の that 節は (should +) 原形。', '最後に全文を訳して確かめる。']
  };

  // ===== 難関レベル =====
  L.hd_eng = {
    goal: '難関大の英語で問われる並べかえ・倒置・挿入・同格・細かい語法・難しい単語に、手順をもって対応できるようになる。',
    intro: '難関大の英語では、知識の量だけでなく【文の構造を見抜く力】が問われます。並べかえ問題も、長文の下線部和訳も、根っこは同じで、「どれが主語で、どれが動詞か」を正確に決められるかどうかです。この単元では、難しい問題に共通する考え方の型と、よく狙われる語法・構文をまとめます。',
    secs: [
      { h: '並べかえ問題の手順', t: '並べかえは、語を1つずつ順番に置いていくと必ず迷います。次の順に考えます。\n① 【動詞を決める】選択肢の中から、主節の V になれる語(時制のある動詞)を探します。\n② 【主語を決める】その V の主語(S)を決めます。\n③ 【かたまりを作る】前置詞 + 名詞、to 不定詞、関係詞節、熟語(prevent A from 〜 など)を、意味のかたまりにまとめます。\n④ 【文型にあてはめる】V の語法(SVO か SVOC か、後ろに何をとるか)に合わせて、かたまりを並べます。\n⑤ 日本語と照らし合わせて確認します。\n日本語の語順にひきずられないことが大切です。',
        ex: [{ q: '日本語に合うように並べかえよう。\n「その事故のせいで、私たちは時間どおりに到着できなかった。」\nThe accident ( arriving / from / prevented / us ) on time.', steps: ['動詞を決める:時制のある動詞は prevented。主語は The accident。', '語法:prevent A from 〜ing=A が〜するのを妨げる。', 'かたまり:prevented + us + from + arriving。', '直訳「その事故は私たちが時間どおりに到着するのを妨げた」→ 日本語と意味が合う。'], a: 'The accident prevented us from arriving on time.' }] },
      { h: '構造を見抜く:倒置・挿入・同格', t: '【倒置】否定語の倒置(Never have I …)のほかに、補語を文頭に出す倒置もあります。\n例:Happy is the man who has true friends.(本当の友人がいる人は幸せだ)→ もとは The man who has true friends is happy.\n長い主語を後ろに回すために、C + V + S の語順になっています。\n【挿入】コンマ・ダッシュではさまれた部分をかっこでくくると骨格が見えます。\n【同格の that】名詞の後ろの that 節が、その名詞の【内容】を説明する形です。fact・news・idea・belief・possibility などの後ろによく来ます。\n関係代名詞の that と見分けるには、【後ろの文が完全か】を確かめます。\n・完全な文 → 同格の that:The fact that he was absent surprised me.(彼が欠席したという事実は、私を驚かせた)\n・不完全な文 → 関係代名詞:The fact that he told me was surprising.(彼が私に話した事実は驚くべきものだった)→ told me の後ろの O が欠けている',
        ex: [{ q: '下線部の that は「同格」か「関係代名詞」か。\n(1) There is no possibility that he will win the race.\n(2) The idea that she suggested was rejected.', steps: ['(1) that の後ろ:he will win the race → S・V・O がそろった完全な文 → 同格。', '(1) possibility の内容(彼がレースに勝つこと)を説明している。', '(2) that の後ろ:she suggested → suggest の O が欠けた不完全な文 → 関係代名詞。'], a: '(1) 同格(彼がレースに勝つ可能性はない)(2) 関係代名詞(彼女が提案した考えは却下された)' }] },
      { h: 'ねらわれやすい語法', t: '【A of B の形をとる動詞】\nrob A of B(A から B を奪う)、remind A of B(A に B を思い出させる)、deprive A of B(A から B を奪う)、inform A of B(A に B を知らせる)\n例:The man robbed her of her bag.(その男は彼女からかばんを奪った)\n※ steal は steal B from A(A から B を盗む)の形。\n【A from 〜ing の形をとる動詞】prevent・keep・stop A from 〜ing(A が〜するのを妨げる)\n【cost と take】It costs + 人 + 金額(〜がかかる:お金)、It takes + 人 + 時間 + to 〜(〜するのに時間がかかる)\n【make・let・have と get】使役の make・let・have は O + 原形、get は O + to 不定詞。\n例:My father let me use his car.(父は私に車を使わせてくれた)\n例:I got my brother to help me.(弟に手伝ってもらった)' },
      { h: '難しい単語への対応', t: '難関大の長文には、英検準1級レベルの単語がふくまれます。すべてを覚えることはできないので、次の2つで対応します。\n【語の部品(接頭辞・語根・接尾辞)から推測する】\n・un-・in-・im-・dis-(否定):unavoidable(避けられない)、inevitable(避けられない)、dishonest(不正直な)\n・pre-(前に)、post-(後に)、re-(再び・もとへ)、inter-(間に)\n・-ology(〜学)、-cide(殺す)、-phobia(恐怖症)\n【文脈から推測する】知らない単語の前後で、言いかえ(or・that is・in other words)、対比(but・while・unlike)、例示(such as・for example)を探します。\n例:Some animals are nocturnal; that is, they are active at night.(夜行性の動物もいる。つまり、夜に活動する)→ that is の後ろから nocturnal=夜行性の、と分かります。' }
    ],
    terms: [['並べかえ問題', '与えられた語を正しい英文に並べる問題。まず V と S を決める'], ['同格の that', '名詞の内容を説明する that 節。後ろは完全な文'], ['補語の倒置', 'C + V + S の語順。長い主語を後ろに回す'], ['接頭辞', '語の前につく部品(un-・pre-・re- など)'], ['語根', '語の中心となる意味をもつ部品']],
    miss: ['並べかえで、日本語の語順どおりに英語を並べてしまう。', '名詞 + that を見ると、すべて関係代名詞だと思ってしまう(後ろが完全なら同格)。', 'rob と steal の語法を混同して、rob her bag や steal her of her bag としてしまう。', '知らない単語で読むのを止めてしまい、前後の言いかえや対比を見ない。'],
    sum: ['並べかえは V → S → かたまり → 文型の順。', '倒置・挿入は、もとの語順に戻して骨格を確かめる。', '名詞 + that 節は、後ろが完全なら同格、不完全なら関係代名詞。', 'rob A of B、prevent A from 〜ing などの語法は形ごと覚える。', '難しい単語は、語の部品と文脈から推測する。']
  };

  // ===== 単語・熟語 =====
  L.e_h5 = {
    goal: '共通テストレベルの英単語を、語源・品詞の変化・多義語の知識を使って、効率よく覚えられるようになる。',
    intro: '英語の長文が読めない理由のいちばんは、【単語を知らないこと】です。共通テストでは、およそ4,000〜5,000語くらいの語彙があると読みやすくなると言われます。とても多く感じますが、単語には「部品」があり、1つの語から仲間の語がいくつも分かります。覚え方を工夫すれば、1語あたりの手間は大きく減らせます。',
    secs: [
      { h: '覚え方の基本:少しずつ、何度も', t: '人は、覚えたことを時間とともに忘れていきます。でも、忘れかけたころに復習すると、記憶は前よりも長持ちするようになります。\nだから単語は、【1日に大量に覚えるより、少しずつを何度もくり返す】ほうが効果的です。\n・1回目:意味を確認して、発音しながら覚える。\n・翌日・3日後・1週間後:もう一度テストして、まちがえた語だけを重点的に見る。\n・例文や長文の中で出会ったら、そこでも意味を思い出す。\n単語帳の「つづり → 意味」だけでなく、「長文の中で意味が思い出せるか」を目標にしましょう。' },
      { h: '語源(接頭辞・語根・接尾辞)で覚える', t: '多くの英単語は、【接頭辞】(前の部品)+【語根】(中心の部品)+【接尾辞】(後ろの部品)からできています。\n【接頭辞】de(下へ・離れて)、re(再び・もとへ)、pre(前に)、ex(外へ)、in・im(中へ/否定)、con・com(いっしょに)、sub(下に)、trans(越えて)\n【語根】port(運ぶ)、spect(見る)、dict(言う)、struct(建てる)、ject(投げる)\n例:import(中へ運ぶ → 輸入する)、export(外へ運ぶ → 輸出する)、transport(越えて運ぶ → 輸送する)\n例:inspect(中を見る → 調べる)、predict(前もって言う → 予言する)、construct(いっしょに建てる → 建設する)\n例:decline(下へ傾く → 減少する・断る)\n【接尾辞】品詞を決めます。\n・名詞:-tion、-ment、-ness、-ity(例:decision、development、kindness、ability)\n・形容詞:-able、-ful、-ous、-ive、-al(例:sustainable、careful、dangerous、active、natural)\n・動詞:-ize、-en、-fy(例:realize、widen、simplify)\n・副詞:-ly(例:quickly)',
        ex: [{ q: '語の部品から、次の単語の意味を推測しよう。\n(1) unpredictable (2) reconstruct', steps: ['(1) un(否定)+ pre(前に)+ dict(言う)+ able(できる)。', '(1) 「前もって言うことができない」→ 予測できない(形容詞)。', '(2) re(再び)+ con(いっしょに)+ struct(建てる)。', '(2) 「再び建てる」→ 再建する・作り直す(動詞)。'], a: '(1) 予測できない (2) 再建する' }] },
      { h: '品詞の変化をセットで覚える', t: '1つの単語を覚えるときは、品詞の変化もいっしょに覚えます。長文でも、文法問題でもよく問われます。\n・decide(決める)→ decision(決定)→ decisive(決定的な)\n・succeed(成功する/あとを継ぐ)→ success(成功)、successful(成功した)/succession(連続・継承)、successive(連続する)\n・economy(経済)→ economic(経済の)、economical(節約になる・経済的な)\n・imagine(想像する)→ imagination(想像力)、imaginary(想像上の)、imaginative(想像力豊かな)\n特に、意味が分かれる形容詞(economic と economical、successful と successive など)はよくねらわれます。' },
      { h: '多義語:いちばん大事な意味から広げる', t: '中学で習ったやさしい単語ほど、ちがう意味で長文に出てきます。中心のイメージから意味を広げて覚えます。\n【address】住所 →(話しかける相手を定める)→ 演説する、(問題に)取り組む\n例:The government must address this issue.(政府はこの問題に取り組まなければならない)\n【issue】問題(論点)、(雑誌の)号、発行する\n【run】走る → 経営する(run a shop)、(液体が)流れる\n【cover】おおう → (範囲を)ふくむ、取材する、(費用を)まかなう\n【case】場合、事例、事件、箱\n知っている意味で訳して文がおかしいときは、【別の意味】を疑いましょう。',
        ex: [{ q: '下線部の意味を答えよう。\nThe meeting will address the problem of food waste.', steps: ['address を「住所」と訳すと、文の意味が通らない → 別の意味を考える。', 'address の後ろに the problem(問題)という目的語がある → 「(問題に)取り組む」。', '文全体:その会議は食品ロスの問題に取り組む予定だ。'], a: '(問題に)取り組む' }] }
    ],
    terms: [['接頭辞', '単語の前につく部品。意味を加える(re-・pre-・un- など)'], ['語根', '単語の中心となる意味をもつ部品(port・spect・dict など)'], ['接尾辞', '単語の後ろにつく部品。品詞を決めることが多い(-tion・-able など)'], ['多義語', '1つの単語で複数の意味をもつ語'], ['派生語', 'もとの単語から、接頭辞・接尾辞をつけてできた語']],
    miss: ['1日にまとめて大量に覚え、その後復習しないので忘れてしまう。', 'つづりと日本語訳を1対1で覚え、多義語の別の意味に気づかない。', 'economic と economical など、似た形の形容詞の意味を区別しない。'],
    sum: ['単語は「少しずつ、何度も」。忘れかけたころに復習する。', '接頭辞・語根・接尾辞の部品から意味を推測する。', '品詞の変化(decide・decision・decisive)をセットで覚える。', '多義語は中心のイメージから意味を広げる。']
  };
  L.e_idiom = {
    goal: 'よく出る英熟語を「かたまり」として覚え、後ろにくる語の形(名詞・ing など)まで正しく使えるようになる。',
    intro: '英熟語は、いくつかの単語が組み合わさって1つの意味を表すものです。look は「見る」、forward は「前へ」ですが、look forward to は「〜を楽しみに待つ」という意味になります。熟語は1語1語の意味を足しても分からないことがあるので、【かたまりのまま、例文の中で覚える】のがコツです。さらに、後ろに何がくるかまで覚えると、文法問題にも強くなります。',
    secs: [
      { h: '熟語の型を知る', t: '英熟語は、形によっていくつかの型に分けられます。型を知っておくと整理しやすくなります。\n【動詞 + 前置詞】look for(〜をさがす)、look after(〜の世話をする = take care of)、depend on(〜にたよる)、deal with(〜を処理する)\n【動詞 + 副詞】give up(あきらめる)、put off(延期する = postpone)、turn down(断る = reject)、carry out(実行する)、figure out(理解する・解決する)\n【動詞 + 副詞 + 前置詞】put up with(〜をがまんする = tolerate)、come up with(〜を思いつく)、look down on(〜を見下す)、catch up with(〜に追いつく)\n【be + 形容詞 + 前置詞】be afraid of(〜をこわがる)、be proud of(〜を誇りに思う)、be different from(〜とちがう)、be familiar with(〜をよく知っている)、be responsible for(〜に責任がある)\n【前置詞のかたまり】because of(〜のために)、in spite of(〜にもかかわらず = despite)、instead of(〜の代わりに)、according to(〜によれば)' },
      { h: '1語の動詞で言いかえる', t: '熟語は、同じ意味の1語の動詞で言いかえられることがよくあります。入試の言いかえ問題でよく出ます。\n・take part in = participate in(〜に参加する)\n・put off = postpone(延期する)\n・put up with = tolerate・stand・bear(〜をがまんする)\n・turn down = reject・refuse(断る)\n・look into = investigate(調査する)\n・make up for = compensate for(〜の埋め合わせをする)\n・call off = cancel(中止する)\n・bring up = raise(育てる)\n1語の動詞を覚えると、長文の中で言いかえに気づきやすくなります。' },
      { h: 'to の後ろに ing がくる熟語', t: '熟語の中の【to が前置詞】のときは、後ろに名詞か動名詞(〜ing)がきます。to 不定詞(to + 原形)とまちがえやすいので要注意です。\n【look forward to 〜ing】〜するのを楽しみに待つ\n例:I\'m looking forward to seeing you.(あなたに会うのを楽しみにしています)× to see\n【be used to 〜ing】〜するのに慣れている\n例:She is used to getting up early.(彼女は早起きに慣れている)\n【object to 〜ing】〜することに反対する\n【when it comes to 〜ing】〜することになると\n【What do you say to 〜ing?】〜するのはどうですか\n注意:【used to + 原形】(以前はよく〜した)は、これとは別の表現です。\n例:I used to get up early.(以前はよく早起きしていた)\nbe動詞があるかどうか、後ろが原形か ing かで見分けます。',
        ex: [{ q: '( ) 内の動詞を正しい形にしよう。\n(1) We are looking forward to ( hear ) from you.\n(2) My father used to ( play ) baseball when he was young.', steps: ['(1) look forward to の to は前置詞 → 後ろは名詞か動名詞。', '(1) hear → hearing。', '(2) be動詞のない used to は「以前はよく〜した」→ 後ろは動詞の原形。'], a: '(1) hearing(お便りを楽しみにお待ちしています)(2) play(父は若いころ、よく野球をしていた)' }] },
      { h: '動詞 + 副詞の熟語と代名詞の位置', t: '【動詞 + 副詞】の熟語で目的語が【代名詞】(it・them・him など)のときは、代名詞を動詞と副詞の【間】に置きます。\n○ Turn off the light. / ○ Turn the light off.(名詞ならどちらでもよい)\n○ Turn it off. / × Turn off it.(代名詞は間に置く)\n例:Please put on your coat. → Please put it on.(それを着てください)\n一方、【動詞 + 前置詞】の熟語では、代名詞も前置詞の後ろに置きます。\n例:I\'m looking for my key. → I\'m looking for it.(× looking it for)\noff・on・up・down・out・away などは副詞として使われることが多い語です。',
        ex: [{ q: '正しいほうを選ぼう。\nThe music is too loud. Please (turn it down / turn down it).', steps: ['turn down(音量を下げる)は「動詞 + 副詞」の熟語。', '目的語が代名詞 it → 動詞と副詞の間に置く。'], a: 'turn it down(音楽がうるさすぎます。音量を下げてください)' }] }
    ],
    terms: [['句動詞', '動詞 + 前置詞・副詞で1つの意味を表すもの(look for、give up など)'], ['前置詞の to', '後ろに名詞・動名詞がくる to。look forward to など'], ['to 不定詞', 'to + 動詞の原形'], ['言いかえ', '熟語と同じ意味の1語(put off = postpone など)']],
    miss: ['look forward to see のように、前置詞の to の後ろに原形を置いてしまう。', 'be used to 〜ing(慣れている)と used to + 原形(以前はよく〜した)を混同する。', 'turn off it のように、代名詞を副詞の後ろに置いてしまう。'],
    sum: ['熟語は、かたまりのまま例文の中で覚える。', '1語の動詞での言いかえ(put off = postpone)もセットで覚える。', 'look forward to・be used to・object to の to は前置詞 → 後ろは〜ing。', '動詞 + 副詞の熟語で、代名詞は間に置く(turn it off)。']
  };

  // ===== 長文読解 =====
  L.e_h6 = {
    goal: '論理マーカー(However・For example・Therefore など)と段落の構造を手がかりに、英語の長文の要点を速く正確に読み取れるようになる。',
    intro: '英語の長文は、ただ単語を順番に訳していくと、何が言いたい文章なのか分からなくなってしまいます。英語の文章には、【話の流れを知らせる道しるべ】があります。それが However(しかし)、For example(たとえば)、Therefore(したがって)などの【論理マーカー】です。道しるべに印をつけながら読むと、次に何が来るかを予想でき、筆者の主張がどこにあるかも見えてきます。',
    secs: [
      { h: '論理マーカーの種類', t: '論理マーカーは、はたらきごとに覚えます。\n【逆接・対比】前と反対のことを言う。However(しかし)、But、Yet、Nevertheless(それにもかかわらず)、On the other hand(一方で)、In contrast(対照的に)\n【追加】前と同じ方向の内容を付け足す。In addition(さらに)、Moreover、Furthermore、Also、Besides\n【例示】前の内容の具体例を挙げる。For example、For instance(たとえば)、such as(〜のような)\n【因果・結論】前の内容から導かれる結果・結論。Therefore(したがって)、Thus、As a result(その結果)、Consequently、So\n【言いかえ・まとめ】前の内容を別の言葉で言う・まとめる。In other words(言いかえれば)、That is(つまり)、In short(要するに)、In conclusion(結論として)\n【順序】First、Second、Then、Finally(最後に)' },
      { h: '主張はどこにあるか', t: '論理マーカーの中でも、筆者の主張を見つけるのに特に大切なのが次の2つの型です。\n【一般論 → However → 主張】\n「Many people believe that 〜(多くの人は〜と信じている)」「It is often said that 〜(よく〜と言われる)」で始まる文は、筆者が否定するための前置きであることが多いです。その後の However の後ろに、筆者の本当の主張が来ます。\n【譲歩 → 主張】\n「Of course 〜 / It is true that 〜(確かに〜)」で相手の意見を一度認めてから、「but / however」で自分の意見を述べる型です。主張は but の後ろにあります。\nまた、For example の後ろは具体例なので、主張そのものではありません。主張は具体例の【前】にある、抽象的な文に書かれています。',
        ex: [{ q: '( A )〜( C ) に入る語を、However・For example・Therefore から選ぼう。\nMany people believe that playing video games is a waste of time. ( A ), recent studies suggest that some games can improve problem-solving skills. ( B ), players of puzzle games often have to plan several steps ahead. ( C ), games may be more useful than we think.', steps: ['(A) 前:ゲームは時間のむだだと信じられている。後:問題解決能力を高めるゲームもある → 反対の内容なので逆接 However。', '(B) 後ろの「パズルゲームでは何手も先を計画しなければならない」は、前の「問題解決能力を高める」の具体例 → For example。', '(C) 後ろの「ゲームは思っているより役に立つかもしれない」は、ここまでの内容から導かれる結論 → Therefore。', '筆者の主張は However の後ろと Therefore の後ろにある。'], a: '(A) However (B) For example (C) Therefore\n(訳)多くの人は、テレビゲームをすることは時間のむだだと信じている。しかし、最近の研究では、問題解決能力を高めるゲームもあることが示されている。たとえば、パズルゲームをする人は、何手も先を計画しなければならないことが多い。したがって、ゲームは私たちが思っているよりも役に立つのかもしれない。' }] },
      { h: '段落の構造:トピックセンテンスを探す', t: '英語の段落(パラグラフ)は、ふつう【1つの段落に1つの主題】という決まりで書かれています。段落は次の3つの部分からできていることが多いです。\n①【トピックセンテンス】その段落の主題(言いたいこと)を短く述べる文。段落の最初に来ることが多い。\n②【サポーティングセンテンス】主題を支える理由・具体例・説明。For example、In addition などで始まることが多い。\n③【コンクルーディングセンテンス】段落のまとめ。Therefore、Thus、In short などで始まることがある。\nこの構造を知っていると、時間がないときでも、【各段落の最初の文】と【論理マーカーの後ろ】を拾い読みするだけで、文章全体の流れがつかめます(パラグラフ・リーディング)。',
        ex: [{ q: '次の段落の主題(トピックセンテンス)はどれか。また、段落の要点を日本語で答えよう。\nSleep is essential for learning. When we sleep, the brain organizes the information we took in during the day. In one experiment, students who slept well after studying remembered more than those who stayed up all night. Thus, cutting sleep to study longer may actually hurt your grades.', steps: ['1文目「睡眠は学習に欠かせない」は抽象的で、段落全体の主題になっている → トピックセンテンス。', '2文目は理由の説明(脳が情報を整理する)、3文目は In one experiment で始まる具体例(実験)。どちらもサポーティングセンテンス。', '4文目は Thus(したがって)で始まるまとめ → コンクルーディングセンテンス。', '主題とまとめを合わせて、要点を短くまとめる。'], a: 'トピックセンテンス:Sleep is essential for learning.(睡眠は学習に欠かせない)\n要点:睡眠中に脳は情報を整理するので、勉強時間を増やすために睡眠をけずると、かえって成績が下がるおそれがある。' }] },
      { h: '本番での読み方の手順', t: '① 【設問を先に見る】何を問われているか(主旨・内容一致・理由など)を確認してから本文を読みます。\n② 【論理マーカーに印をつけながら読む】However・Therefore には丸、For example には下線など、自分で決めた印をつけます。\n③ 【マーカーの先を予想する】However を見たら「前と反対のことが来る」、For example を見たら「具体例が来る」と予想しながら読むと、速く読めます。\n④ 【段落ごとに一言でまとめる】段落を読み終えるたびに、余白に「〜の問題点」「〜の具体例」などと短くメモします。\n⑤ 【選択肢は本文の言いかえを探す】正解の選択肢は、本文の表現を別の言葉で言いかえていることが多いです。本文と同じ単語が多いだけの選択肢には注意しましょう。' }
    ],
    terms: [['論理マーカー', '文と文、段落と段落の関係を示す語句(However・Therefore など)'], ['トピックセンテンス', '段落の主題を述べる文。段落の最初に来ることが多い'], ['サポーティングセンテンス', '主題を支える理由・具体例・説明の文'], ['譲歩', '相手の意見を「確かに〜」と一度認めること'], ['パラグラフ・リーディング', '各段落の主題をつかみながら、文章全体の流れを読む方法']],
    miss: ['For example の後ろの具体例を、筆者の主張だと思ってしまう。', '「Many people believe 〜」で始まる一般論を、筆者の意見だと思ってしまう(多くの場合、筆者はそれを否定する)。', '本文と同じ単語が多い選択肢を、内容を確かめずに選んでしまう。', 'Nevertheless や On the other hand を、追加の意味だと思ってしまう(逆接・対比)。'],
    sum: ['論理マーカーは 逆接・追加・例示・因果・言いかえ に分けて覚える。', 'However・but の後ろ、Therefore の後ろに主張や結論が来やすい。', '具体例の前にある抽象的な文が主張。', '段落は トピックセンテンス → サポート → まとめ。最初の文に注目する。', '設問を先に見て、マーカーに印をつけ、段落ごとにメモしながら読む。']
  };
})(WPS.LESSONS);
